@pytest.mark.parametrize("null_interceptor", [True, False])
def test_update_rest_interceptors(null_interceptor):
    transport = transports.SqlInstancesServiceRestTransport(
        credentials=ga_credentials.AnonymousCredentials(),
        interceptor=None
        if null_interceptor
        else transports.SqlInstancesServiceRestInterceptor(),
    )
    client = SqlInstancesServiceClient(transport=transport)

    with (
        mock.patch.object(type(client.transport._session), "request") as req,
        mock.patch.object(path_template, "transcode") as transcode,
        mock.patch.object(
            transports.SqlInstancesServiceRestInterceptor, "post_update"
        ) as post,
        mock.patch.object(
            transports.SqlInstancesServiceRestInterceptor, "post_update_with_metadata"
        ) as post_with_metadata,
        mock.patch.object(
            transports.SqlInstancesServiceRestInterceptor, "pre_update"
        ) as pre,
    ):
        pre.assert_not_called()
        post.assert_not_called()
        post_with_metadata.assert_not_called()
        pb_message = cloud_sql.SqlInstancesUpdateRequest.pb(
            cloud_sql.SqlInstancesUpdateRequest()
        )
        transcode.return_value = {
            "method": "post",
            "uri": "my_uri",
            "body": pb_message,
            "query_params": pb_message,
        }

        req.return_value = mock.Mock()
        req.return_value.status_code = 200
        req.return_value.headers = {"header-1": "value-1", "header-2": "value-2"}
        return_value = cloud_sql_resources.Operation.to_json(
            cloud_sql_resources.Operation()
        )
        req.return_value.content = return_value

        request = cloud_sql.SqlInstancesUpdateRequest()
        metadata = [
            ("key", "val"),
            ("cephalopod", "squid"),
        ]
        pre.return_value = request, metadata
        post.return_value = cloud_sql_resources.Operation()
        post_with_metadata.return_value = cloud_sql_resources.Operation(), metadata

        client.update(
            request,
            metadata=[
                ("key", "val"),
                ("cephalopod", "squid"),
            ],
        )

        pre.assert_called_once()
        post.assert_called_once()
        post_with_metadata.assert_called_once()


