def test_release_ssrs_lease_empty_call_rest():
    client = SqlInstancesServiceClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport="rest",
    )

    # Mock the actual call, and fake the request.
    with mock.patch.object(
        type(client.transport.release_ssrs_lease), "__call__"
    ) as call:
        client.release_ssrs_lease(request=None)

        # Establish that the underlying stub method was called.
        call.assert_called()
        _, args, _ = call.mock_calls[0]
        request_msg = cloud_sql.SqlInstancesReleaseSsrsLeaseRequest()
        assert args[0] == request_msg


