def test_sql_instances_service_base_transport_error():
    # Passing both a credentials object and credentials_file should raise an error
    with pytest.raises(core_exceptions.DuplicateCredentialArgs):
        transport = transports.SqlInstancesServiceTransport(
            credentials=ga_credentials.AnonymousCredentials(),
            credentials_file="credentials.json",
        )


def test_sql_instances_service_base_transport():
    # Instantiate the base transport.
    with mock.patch(
        "google.cloud.sql_v1beta4.services.sql_instances_service.transports.SqlInstancesServiceTransport.__init__"
    ) as Transport:
        Transport.return_value = None
        transport = transports.SqlInstancesServiceTransport(
            credentials=ga_credentials.AnonymousCredentials(),
        )

    # Every method on the transport should just blindly
    # raise NotImplementedError.
    methods = (
        "add_server_ca",
        "add_server_certificate",
        "add_entra_id_certificate",
        "clone",
        "delete",
        "demote_master",
        "demote",
        "export",
        "failover",
        "reencrypt",
        "get",
        "import_",
        "insert",
        "list",
        "list_server_cas",
        "list_server_certificates",
        "list_entra_id_certificates",
        "patch",
        "promote_replica",
        "switchover",
        "reset_ssl_config",
        "restart",
        "restore_backup",
        "rotate_server_ca",
        "rotate_server_certificate",
        "rotate_entra_id_certificate",
        "start_replica",
        "stop_replica",
        "truncate_log",
        "update",
        "create_ephemeral",
        "reschedule_maintenance",
        "verify_external_sync_settings",
        "start_external_sync",
        "perform_disk_shrink",
        "get_disk_shrink_config",
        "reset_replica_size",
        "get_latest_recovery_time",
        "execute_sql",
        "acquire_ssrs_lease",
        "release_ssrs_lease",
        "pre_check_major_version_upgrade",
        "point_in_time_restore",
    )
    for method in methods:
        with pytest.raises(NotImplementedError):
            getattr(transport, method)(request=object())

    with pytest.raises(NotImplementedError):
        transport.close()

    # Catch all for all remaining methods and properties
    remainder = [
        "kind",
    ]
    for r in remainder:
        with pytest.raises(NotImplementedError):
            getattr(transport, r)()


